<?php
require __DIR__.'/../includes/auth.php'; $page_title="Riwayat Peminjaman"; include __DIR__.'/../includes/header.php'; require __DIR__.'/../includes/koneksi.php';
$anggotaId=filter_input(INPUT_GET,'anggota_id',FILTER_VALIDATE_INT)?:0; $anggota=$pdo->query('SELECT id,nama,no_anggota FROM anggota ORDER BY nama')->fetchAll(PDO::FETCH_ASSOC); $riwayat=[];
if($anggotaId>0){$stmt=$pdo->prepare("SELECT p.id,p.tanggal_pinjam,p.tanggal_kembali,p.status,b.judul,b.pengarang FROM peminjaman p JOIN buku b ON b.id=p.buku_id WHERE p.anggota_id=:id ORDER BY p.tanggal_pinjam DESC,p.id DESC");$stmt->execute(['id'=>$anggotaId]);$riwayat=$stmt->fetchAll(PDO::FETCH_ASSOC);}
?><section><h2>Riwayat Peminjaman</h2><form method="get" action="riwayat.php"><p><label for="anggota_id">Pilih Anggota</label><select id="anggota_id" name="anggota_id" required><option value="">-- Pilih anggota --</option><?php foreach($anggota as $a): ?><option value="<?php echo (int)$a['id']; ?>" <?php echo $anggotaId===(int)$a['id']?'selected':''; ?>><?php echo e($a['nama']); ?> (<?php echo e($a['no_anggota']); ?>)</option><?php endforeach; ?></select> <button type="submit">Lihat Riwayat</button></p></form>
<?php if($anggotaId>0): ?><div class="table-responsive"><table><thead><tr><th>ID</th><th>Buku</th><th>Pengarang</th><th>Tanggal Pinjam</th><th>Tanggal Kembali</th><th>Status</th></tr></thead><tbody><?php if(!$riwayat): ?><tr><td colspan="6">Belum ada riwayat peminjaman untuk anggota ini.</td></tr><?php else: foreach($riwayat as $p): ?><tr><td><?php echo (int)$p['id']; ?></td><td><?php echo e($p['judul']); ?></td><td><?php echo e($p['pengarang']); ?></td><td><?php echo e($p['tanggal_pinjam']); ?></td><td><?php echo e($p['tanggal_kembali']??'-'); ?></td><td><?php echo $p['status']==='selesai'?'Selesai':'Dipinjam'; ?></td></tr><?php endforeach; endif; ?></tbody></table></div><?php endif; ?></section><?php include __DIR__.'/../includes/footer.php'; ?>
